function stepActor(a,dt){if(a.stun>0){a.stun-=dt;return;}
  a.progress??=0;
  if(a.progress===0){a.x=Math.round(a.x);a.y=Math.round(a.y);if(a===player){if((a.want.x||a.want.y)&&canMove(a.x,a.y,a.want))a.dir={...a.want};const current=currents.get(key(a.x,a.y));if(current){const forced=DIRS.find(d=>d.name===current);if(canMove(a.x,a.y,forced))a.dir={...forced};}}
    else chooseGhostDirection(a);
    if((!a.dir.x&&!a.dir.y)||!canMove(a.x,a.y,a.dir)){a.dir={x:0,y:0};return;}
  }
  const speed=a.speed*(a===player&&ice.has(key(Math.round(a.x),Math.round(a.y)))?.7:1);
  const delta=Math.min(speed*dt,1-a.progress);a.x+=a.dir.x*delta;a.y+=a.dir.y*delta;a.progress+=delta;
  if(a.progress>=.999){a.x=Math.round(a.x);a.y=Math.round(a.y);a.progress=0;onEnter(a,a.x,a.y);}
}

